(async () => {
  const { accessSync, constants } = await import('node:fs');
  const inputPath = process.env.INPUT_DOCX_PATH;
  if (!inputPath) {
    throw new Error('Missing INPUT_DOCX_PATH env var');
  }
  try {
    accessSync(inputPath, constants.R_OK);
  } catch (e) {
    throw new Error('Input file not accessible: ' + inputPath);
  }
  globalThis.inputPath = inputPath;
})();

(async () => {
  const mod = await import('mammoth');
  const mammoth = mod.default || mod;
  if (typeof mammoth.convertToMarkdown !== 'function') {
    throw new Error('mammoth: convertToMarkdown not available');
  }
  const result = await mammoth.convertToMarkdown({ path: globalThis.inputPath });
  globalThis.markdown = result.value;
})();

(async () => {
  if (typeof globalThis.markdown !== 'string') {
    throw new Error('markdown result missing');
  }
  console.log(JSON.stringify({ markdown: globalThis.markdown }));
})();
